import Link from "next/link";
import { costs } from "./costs";

// One side of the Token Costs tab (MVP1-E8-16, Nikhil's structure of 27 Nov 2026): Product or
// Engineering, each with what it has consumed so far (stories, then pre-requisites) and what the
// remaining stories of the latest roadmap are projected to cost. Every figure comes from costs.ts,
// generated by `npm run costs` from the ledger and docs/process/token-classes.json.

const ISSUES = "https://github.com/founder2863/01scale.com/issues";

function usd(value: number | null) {
  return value === null
    ? "pending"
    : `$${value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function mtok(value: number) {
  return `${(value / 1_000_000).toFixed(1)}M`;
}

type Side = "product" | "engineering";

const LABEL: Record<Side, string> = { product: "Product", engineering: "Engineering" };

export function TokenSide({ side, letter }: { side: Side; letter: string }) {
  const s = costs.split[side];
  const roadmap = costs.split.roadmap;
  return (
    <section className="token-side" aria-labelledby={`token-side-${side}`}>
      <h3 className="section-subtitle" id={`token-side-${side}`}>
        ({letter}) {LABEL[side]}
      </h3>
      <div className="stat-row">
        <div className="stat">
          <span className="stat-value">{usd(s.soFar)}</span>
          <span className="stat-label">Consumed so far</span>
        </div>
        <div className="stat">
          <span className="stat-value">{usd(s.projectedCost)}</span>
          <span className="stat-label">Projected, {s.projectedStories} remaining stories</span>
        </div>
        <div className="stat">
          <span className="stat-value">{usd(s.total)}</span>
          <span className="stat-label">{LABEL[side]} total</span>
        </div>
      </div>

      <h4 className="cost-more-title">Consumed so far: stories</h4>
      <table className="cost-table cost-table-wide">
        <thead>
          <tr>
            <th scope="col">Story</th>
            <th scope="col">Share</th>
            <th scope="col">Tokens</th>
            <th scope="col">Build cost</th>
            <th scope="col">Rework cost</th>
            <th scope="col">Total</th>
            <th scope="col">Token yield</th>
          </tr>
        </thead>
        <tbody>
          {s.stories.map((story) => (
            <tr key={story.key}>
              <th scope="row">{story.name}</th>
              <td data-label="Share" title={story.why}>
                {story.share}%
              </td>
              <td data-label="Tokens">{mtok(story.tokens)}</td>
              <td data-label="Build cost">{usd(story.buildCost)}</td>
              <td data-label="Rework cost">{usd(story.reworkCost)}</td>
              <td data-label="Total">
                {usd(story.totalCost)}
                {story.pending && <span className="cost-pending"> + pending</span>}
              </td>
              <td data-label="Token yield">
                <span className="yield">
                  <span className="yield-bar" style={{ width: `${story.yield ?? 0}%` }} />
                </span>
                {story.yield}%
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <th scope="row">Total</th>
            <td data-label="Share" />
            <td data-label="Tokens">{mtok(s.storyTotals.tokens)}</td>
            <td data-label="Build cost">{usd(s.storyTotals.buildCost)}</td>
            <td data-label="Rework cost">{usd(s.storyTotals.reworkCost)}</td>
            <td data-label="Total">
              {usd(s.storyTotals.cost)}
              {s.storyTotals.pending && <span className="cost-pending"> + pending</span>}
            </td>
            <td data-label="Token yield" />
          </tr>
        </tfoot>
      </table>

      <h4 className="cost-more-title">Consumed so far: pre-requisites</h4>
      <table className="cost-table cost-table-small">
        <thead>
          <tr>
            <th scope="col">Area</th>
            <th scope="col">Requests</th>
            <th scope="col">Tokens</th>
            <th scope="col">Cost</th>
          </tr>
        </thead>
        <tbody>
          {s.prereq.map((area) => (
            <tr key={area.name}>
              <th scope="row">{area.name}</th>
              <td data-label="Requests">{area.requests}</td>
              <td data-label="Tokens">{mtok(area.tokens)}</td>
              <td data-label="Cost">{usd(area.cost)}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <th scope="row">Total</th>
            <td data-label="Requests">{s.prereqTotals.requests}</td>
            <td data-label="Tokens">{mtok(s.prereqTotals.tokens)}</td>
            <td data-label="Cost">{usd(s.prereqTotals.cost)}</td>
          </tr>
        </tfoot>
      </table>

      <details className="cost-more">
        <summary>
          Projected for the remaining stories ({s.projectedStories}, {usd(s.projectedCost)})
        </summary>
        <p className="note">
          The stories {roadmap ? <Link href={roadmap.href}>roadmap {roadmap.slug}</Link> : "the roadmap"} gives
          to {side === "product" ? "a product manager" : "an engineer"} and not yet built, priced with its token rule.
        </p>
        <table className="cost-table cost-table-small">
          <thead>
            <tr>
              <th scope="col">Story</th>
              <th scope="col">Size</th>
              <th scope="col">Projected cost</th>
            </tr>
          </thead>
          <tbody>
            {s.projected.map((story) => (
              <tr key={story.id}>
                <th scope="row">
                  {story.issue ? <a href={`${ISSUES}/${story.issue}`}>{story.id}</a> : story.id} · {story.title}
                </th>
                <td data-label="Size">{story.size}</td>
                <td data-label="Projected cost">{usd(story.cost)}</td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <th scope="row">Total</th>
              <td data-label="Size" />
              <td data-label="Projected cost">{usd(s.projectedCost)}</td>
            </tr>
          </tfoot>
        </table>
      </details>
    </section>
  );
}

// (d) Total token cost: actual so far and projected, for each side and in all.
export function TokenTotal() {
  const sp = costs.split;
  const rows: { label: string; soFar: number; projected: number; total: number }[] = [
    { label: "Product", soFar: sp.product.soFar, projected: sp.product.projectedCost, total: sp.product.total },
    { label: "Engineering", soFar: sp.engineering.soFar, projected: sp.engineering.projectedCost, total: sp.engineering.total },
  ];
  return (
    <section aria-labelledby="token-total">
      <h3 className="section-subtitle" id="token-total">
        (d) Total token cost
      </h3>
      <table className="cost-table cost-table-small">
        <thead>
          <tr>
            <th scope="col" />
            <th scope="col">Actual so far</th>
            <th scope="col">Projected</th>
            <th scope="col">Total</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.label}>
              <th scope="row">{row.label}</th>
              <td data-label="Actual so far">{usd(row.soFar)}</td>
              <td data-label="Projected">{usd(row.projected)}</td>
              <td data-label="Total">{usd(row.total)}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <th scope="row">Total token cost</th>
            <td data-label="Actual so far">{usd(sp.soFar)}</td>
            <td data-label="Projected">{usd(sp.projectedCost)}</td>
            <td data-label="Total">{usd(sp.total)}</td>
          </tr>
        </tfoot>
      </table>
      {sp.tokensWhy && <p className="note">Projected: {sp.tokensWhy}</p>}
    </section>
  );
}
